Boolean nvfs_log_add( Nvfs_Log log  , Nvfs_Log_Data * data )
{
    UInt16 i ; 

    log->index %= log->number_of_elements ; 
        
    for( i = 0 ; i < log->element_size ; i ++ ) 
    {
        log->buffer[(UInt16)log->index*log->element_size + i] = (UInt8)data[i] ;        
    }
        
    
    log->index ++ ;
    
    return nvfs_log_save( log );    
}

